/* Cartas de dominio del SRD de Daggerheart (mayo 2025), traducidas al español (en: nombre original en inglés).
   d: dominio, lv: nivel, ty: Spell/Ability/Grimoire, rc: coste de recuperación. */
const CARTAS_DOMINIO=[{"id":"rune-ward","n":"Guarda rúnica","en":"Rune Ward","lv":1,"d":"Arcana","ty":"Spell","rc":0,"t":"Tienes una baratija muy personal que puede imbuirse de magia protectora y llevarse como guarda, tú o un aliado. Describe qué es y por qué es importante para ti. Quien lleve la guarda puede gastar una Esperanza para reducir en 1d8 el daño que recibe. Si el dado de la guarda saca un 8, el poder de la guarda se acaba después de reducir el daño este turno. Se puede recargar gratis en tu siguiente descanso."},
{"id":"unleash-chaos","n":"Desatar el caos","en":"Unleash Chaos","lv":1,"d":"Arcana","ty":"Spell","rc":1,"t":"Al principio de una sesión, pon en esta carta tantas fichas como tu rasgo de Lanzamiento. Haz una Tirada de Lanzamiento contra un objetivo a distancia Lejana y gasta las fichas que quieras para canalizar energía pura de tu interior y desatarla contra él. Si tienes éxito, tira tantos d10 como fichas hayas gastado e inflige esa cantidad de daño mágico al objetivo. Marca un Estrés para reponer las fichas de esta carta (hasta tu rasgo de Lanzamiento). Al final de cada sesión, quita las fichas que no hayas gastado."},
{"id":"wall-walk","n":"Caminar por los muros","en":"Wall Walk","lv":1,"d":"Arcana","ty":"Spell","rc":1,"t":"Gasta una Esperanza para que una criatura a la que puedas tocar trepe por paredes y techos con la misma facilidad con la que camina por el suelo. Dura hasta el final de la escena o hasta que vuelvas a lanzar Caminar por los muros."},
{"id":"cinder-grasp","n":"Puño de ascuas","en":"Cinder Grasp","lv":2,"d":"Arcana","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Cuerpo a cuerpo. Si tienes éxito, el objetivo estalla en llamas al instante, recibe 1d20+3 de daño mágico y queda Ardiendo de forma temporal. Cuando una criatura actúa mientras está Ardiendo, recibe 2d6 de daño mágico extra si sigue Ardiendo al final de su acción."},
{"id":"floating-eye","n":"Ojo flotante","en":"Floating Eye","lv":2,"d":"Arcana","ty":"Spell","rc":0,"t":"Gasta una Esperanza para crear un pequeño orbe flotante que puedes mover a cualquier punto a distancia Muy Lejana. Mientras dure el hechizo, puedes ver a través del orbe como si miraras desde su posición. Puedes pasar libremente de tus propios sentidos a la vista del orbe. Si el orbe recibe daño o sale del alcance, el hechizo termina."},
{"id":"counterspell","n":"Contrahechizo","en":"Counterspell","lv":3,"d":"Arcana","ty":"Spell","rc":2,"t":"Puedes interrumpir un efecto mágico que esté ocurriendo haciendo una Tirada de Reacción con tu rasgo de Lanzamiento. Si tienes éxito, el efecto se detiene, se evitan sus consecuencias y esta carta va a tu baúl."},
{"id":"flight","n":"Vuelo","en":"Flight","lv":3,"d":"Arcana","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (15). Si tienes éxito, pon en esta carta tantas fichas como tu Agilidad (mínimo 1). Cuando hagas una Tirada de Acción mientras vuelas, gasta una ficha de esta carta. Cuando se resuelva la acción que gasta la última ficha, desciendes hasta el suelo justo debajo de ti."},
{"id":"blink-out","n":"Parpadeo","en":"Blink Out","lv":4,"d":"Arcana","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (12). Si tienes éxito, gasta una Esperanza para teletransportarte a otro punto que puedas ver a distancia Lejana. Si hay criaturas dispuestas a distancia Muy Cercana, gasta una Esperanza más por cada una para llevarlas contigo."},
{"id":"preservation-blast","n":"Estallido protector","en":"Preservation Blast","lv":4,"d":"Arcana","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento contra todos los objetivos a distancia Cuerpo a cuerpo. Los objetivos contra los que tengas éxito salen despedidos hasta distancia Lejana y reciben d8+3 de daño mágico usando tu rasgo de Lanzamiento."},
{"id":"chain-lightning","n":"Rayo en cadena","en":"Chain Lightning","lv":5,"d":"Arcana","ty":"Spell","rc":1,"t":"Marca 2 de Estrés para hacer una Tirada de Lanzamiento y desatar rayos sobre todos los objetivos a distancia Cercana. Los objetivos contra los que tengas éxito deben hacer una Tirada de Reacción con una Dificultad igual al resultado de tu Tirada de Lanzamiento. Los que fallen reciben 2d8+4 de daño mágico. Los demás adversarios a los que aún no haya alcanzado el Rayo en cadena y que estén a distancia Cercana de un objetivo que haya recibido daño también deben hacer la Tirada de Reacción. Los que fallen reciben 2d8+4 de daño mágico. La cadena sigue hasta que no queden adversarios a su alcance."},
{"id":"premonition","n":"Premonición","en":"Premonition","lv":5,"d":"Arcana","ty":"Spell","rc":2,"t":"Puedes canalizar energía arcana para tener visiones del futuro. Una vez por descanso largo, justo después de que el DM cuente las consecuencias de una tirada tuya, puedes deshacer el movimiento y sus consecuencias como si nunca hubieran ocurrido y hacer otro movimiento en su lugar."},
{"id":"rift-walker","n":"Caminante de grietas","en":"Rift Walker","lv":6,"d":"Arcana","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (15). Si tienes éxito, dejas una marca arcana en el suelo donde estás. La siguiente vez que lances con éxito Caminante de grietas, se abre una grieta en el espacio que ofrece un paso seguro de vuelta al punto exacto de la marca. La grieta sigue abierta hasta que decidas cerrarla o lances otro hechizo. Puedes dejar el hechizo cuando quieras para volver a lanzar Caminante de grietas y poner la marca en otro sitio."},
{"id":"telekinesis","n":"Telequinesis","en":"Telekinesis","lv":6,"d":"Arcana","ty":"Spell","rc":0,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Lejana. Si tienes éxito, puedes usar tu mente para moverlo a cualquier punto a distancia Lejana de donde estaba. Puedes lanzar al objetivo levantado como ataque haciendo otra Tirada de Lanzamiento contra un segundo objetivo. Si tienes éxito, inflige d12+4 de daño físico al segundo objetivo usando tu Competencia. Después, el hechizo termina."},
{"id":"arcana-touched","n":"Tocado por la Arcana","en":"Arcana-Touched","lv":7,"d":"Arcana","ty":"Ability","rc":2,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Arcana, obtienes estos beneficios:\n• +1 a tus Tiradas de Lanzamiento.\n• Una vez por descanso, puedes intercambiar los resultados de tus dados de Esperanza y de Miedo."},
{"id":"cloaking-blast","n":"Estallido velado","en":"Cloaking Blast","lv":7,"d":"Arcana","ty":"Spell","rc":2,"t":"Cuando hagas con éxito una Tirada de Lanzamiento para lanzar otro hechizo, puedes gastar una Esperanza para quedar Velado. Mientras estés Velado, nadie te ve si estás quieto cuando un adversario se mueve hasta donde normalmente te vería. Cuando te muevas hacia el campo de visión de un adversario o dentro de él, o cuando ataques, dejas de estar Velado."},
{"id":"arcane-reflection","n":"Reflejo arcano","en":"Arcane Reflection","lv":8,"d":"Arcana","ty":"Spell","rc":1,"t":"Cuando vayas a recibir daño mágico, puedes gastar las Esperanzas que quieras para tirar esa cantidad de d6. Si alguno saca un 6, el ataque se refleja contra quien lo lanzó, y es él quien recibe el daño."},
{"id":"confusing-aura","n":"Aura confusa","en":"Confusing Aura","lv":8,"d":"Arcana","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (14). Una vez por descanso largo, si tienes éxito, creas sobre tu cuerpo una capa de ilusión que hace difícil saber dónde estás exactamente. Marca el Estrés que quieras para crear esa cantidad de capas adicionales. Cuando un adversario te ataque, tira tantos d6 como capas tengas activas. Si alguno saca un 5 o más, se destruye una capa del aura y el ataque falla. Si todos sacan 4 o menos, recibes el daño y el hechizo termina."},
{"id":"earthquake","n":"Terremoto","en":"Earthquake","lv":9,"d":"Arcana","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (16). Una vez por descanso, si tienes éxito, todos los objetivos a distancia Muy Lejana que no estén volando deben hacer una Tirada de Reacción (18). Los que fallen reciben 3d10+8 de daño físico y quedan Vulnerables de forma temporal. Los que tengan éxito reciben la mitad del daño. Además, cuando tengas éxito en la Tirada de Lanzamiento, todo el terreno a distancia Muy Lejana se vuelve difícil de atravesar y las estructuras a esa distancia pueden sufrir daños o derrumbarse."},
{"id":"sensory-projection","n":"Proyección sensorial","en":"Sensory Projection","lv":9,"d":"Arcana","ty":"Spell","rc":0,"t":"Una vez por descanso, haz una Tirada de Lanzamiento (15). Si tienes éxito, entras en una visión que te deja ver y oír con claridad cualquier lugar en el que hayas estado antes, como si estuvieras allí en ese momento. En la visión te mueves libremente, sin las leyes ni los obstáculos de un cuerpo físico. Este hechizo no se puede detectar por medios normales ni mágicos. Sales de la visión al recibir daño o al lanzar otro hechizo."},
{"id":"adjust-reality","n":"Ajustar la realidad","en":"Adjust Reality","lv":10,"d":"Arcana","ty":"Spell","rc":1,"t":"Después de que tú o un aliado dispuesto hagáis cualquier tirada, puedes gastar 5 de Esperanza para cambiar el resultado numérico de esa tirada por el que elijas. El resultado tiene que ser posible con esos dados."},
{"id":"falling-sky","n":"Cielo que cae","en":"Falling Sky","lv":10,"d":"Arcana","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra todos los adversarios a distancia Lejana. Marca el Estrés que quieras para que caigan del cielo esquirlas de energía arcana. Los objetivos contra los que tengas éxito reciben 1d20+2 de daño mágico por cada Estrés marcado."},
{"id":"get-back-up","n":"Levántate","en":"Get Back Up","lv":1,"d":"Blade","ty":"Ability","rc":1,"t":"Cuando recibas daño Grave, puedes marcar un Estrés para reducir la gravedad un umbral."},
{"id":"not-good-enough","n":"No es suficiente","en":"Not Good Enough","lv":1,"d":"Blade","ty":"Ability","rc":1,"t":"Cuando tires tus dados de daño, puedes repetir los 1 y los 2."},
{"id":"whirlwind","n":"Torbellino","en":"Whirlwind","lv":1,"d":"Blade","ty":"Ability","rc":0,"t":"Cuando aciertes un ataque contra un objetivo a distancia Muy Cercana, puedes gastar una Esperanza para usar el ataque contra todos los demás objetivos a distancia Muy Cercana. Los adversarios adicionales contra los que tengas éxito con esta habilidad reciben la mitad del daño."},
{"id":"a-soldiers-bond","n":"Lazo de soldados","en":"A Soldier’s Bond","lv":2,"d":"Blade","ty":"Ability","rc":1,"t":"Una vez por descanso largo, cuando halagues a alguien o le preguntes por algo que se le da bien, ambos ganáis 3 de Esperanza."},
{"id":"reckless","n":"Temerario","en":"Reckless","lv":2,"d":"Blade","ty":"Ability","rc":1,"t":"Marca un Estrés para tener ventaja en un ataque."},
{"id":"scramble","n":"Escabullirse","en":"Scramble","lv":3,"d":"Blade","ty":"Ability","rc":1,"t":"Una vez por descanso, cuando una criatura a distancia Cuerpo a cuerpo vaya a hacerte daño, puedes evitar el ataque y alejarte a salvo fuera del alcance Cuerpo a cuerpo del enemigo."},
{"id":"versatile-fighter","n":"Luchador versátil","en":"Versatile Fighter","lv":3,"d":"Blade","ty":"Ability","rc":1,"t":"Puedes usar un rasgo distinto con un arma equipada, en lugar del rasgo que pide el arma. Cuando inflijas daño, puedes marcar un Estrés para usar el resultado máximo de uno de tus dados de daño en vez de tirarlo."},
{"id":"deadly-focus","n":"Concentración letal","en":"Deadly Focus","lv":4,"d":"Blade","ty":"Ability","rc":2,"t":"Una vez por descanso, puedes concentrarte por completo en un objetivo que elijas. Hasta que ataques a otra criatura, derrotes al objetivo o termine la batalla, ganas +1 a tu Competencia."},
{"id":"fortified-armor","n":"Armadura reforzada","en":"Fortified Armor","lv":4,"d":"Blade","ty":"Ability","rc":0,"t":"Mientras lleves armadura, ganas +2 a tus umbrales de daño."},
{"id":"champions-edge","n":"Filo del campeón","en":"Champion’s Edge","lv":5,"d":"Blade","ty":"Ability","rc":1,"t":"Cuando consigas un éxito crítico en un ataque, puedes gastar hasta 3 de Esperanza y elegir una de estas opciones por cada Esperanza gastada:\n• Recuperas un Punto de Golpe.\n• Recuperas una casilla de Armadura.\n• El objetivo debe marcar un Punto de Golpe adicional.\nNo puedes elegir la misma opción más de una vez."},
{"id":"vitality","n":"Vitalidad","en":"Vitality","lv":5,"d":"Blade","ty":"Ability","rc":0,"t":"Cuando elijas esta carta, ganas para siempre dos de estos beneficios:\n• Una casilla de Estrés.\n• Una casilla de Punto de Golpe.\n• +2 a tus umbrales de daño.\nDespués, pon esta carta en tu baúl para siempre."},
{"id":"battle-hardened","n":"Curtido en batalla","en":"Battle-Hardened","lv":6,"d":"Blade","ty":"Ability","rc":2,"t":"Una vez por descanso largo, cuando fueras a hacer un Movimiento de Muerte, puedes gastar una Esperanza para recuperar un Punto de Golpe en su lugar."},
{"id":"rage-up","n":"Montar en cólera","en":"Rage Up","lv":6,"d":"Blade","ty":"Ability","rc":1,"t":"Antes de atacar, puedes marcar un Estrés para ganar a tu tirada de daño un bonificador igual al doble de tu Fuerza. Puedes montar en cólera dos veces por ataque."},
{"id":"blade-touched","n":"Tocado por el Filo","en":"Blade-Touched","lv":7,"d":"Blade","ty":"Ability","rc":1,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Filo, obtienes estos beneficios:\n• +2 a tus tiradas de ataque.\n• +4 a tu umbral de daño Grave."},
{"id":"glancing-blow","n":"Golpe de refilón","en":"Glancing Blow","lv":7,"d":"Blade","ty":"Ability","rc":1,"t":"Cuando falles un ataque, puedes marcar un Estrés para infligir el daño del arma usando la mitad de tu Competencia."},
{"id":"battle-cry","n":"Grito de guerra","en":"Battle Cry","lv":8,"d":"Blade","ty":"Ability","rc":2,"t":"Una vez por descanso largo, mientras cargas hacia el peligro, puedes soltar un grito que inspira a tus aliados. Todos los aliados que te oigan recuperan un Estrés y ganan una Esperanza. Además, tus aliados tienen ventaja en las tiradas de ataque hasta que tú o un aliado saquéis un fallo con Miedo."},
{"id":"frenzy","n":"Frenesí","en":"Frenzy","lv":8,"d":"Blade","ty":"Ability","rc":3,"t":"Una vez por descanso largo, puedes entrar en Frenesí hasta que no quede ningún adversario a la vista. Mientras estés en Frenesí, no puedes usar casillas de Armadura, y ganas +10 a tus tiradas de daño y +8 a tu umbral de daño Grave."},
{"id":"gore-and-glory","n":"Sangre y gloria","en":"Gore and Glory","lv":9,"d":"Blade","ty":"Ability","rc":2,"t":"Cuando consigas un éxito crítico en un ataque con arma, ganas una Esperanza más o recuperas un Estrés más. Además, cuando inflijas daño suficiente para derrotar a un enemigo, ganas una Esperanza o recuperas un Estrés."},
{"id":"deft-maneuvers","n":"Maniobras hábiles","en":"Deft Maneuvers","lv":1,"d":"Bone","ty":"Ability","rc":0,"t":"Una vez por descanso, marca un Estrés para correr a cualquier punto a distancia Lejana sin hacer una Tirada de Agilidad para llegar. Si terminas el movimiento a distancia Cuerpo a cuerpo de un adversario y lo atacas de inmediato, ganas +1 a la tirada de ataque."},
{"id":"i-see-it-coming","n":"Lo veo venir","en":"I See It Coming","lv":1,"d":"Bone","ty":"Ability","rc":1,"t":"Cuando te ataquen desde más allá de distancia Cuerpo a cuerpo, puedes marcar un Estrés para tirar un d4 y sumar el resultado a tu Evasión contra ese ataque."},
{"id":"untouchable","n":"Intocable","en":"Untouchable","lv":1,"d":"Bone","ty":"Ability","rc":1,"t":"Ganas a tu Evasión un bonificador igual a la mitad de tu Agilidad."},
{"id":"ferocity","n":"Ferocidad","en":"Ferocity","lv":2,"d":"Bone","ty":"Ability","rc":2,"t":"Cuando hagas que un adversario marque 1 o más Puntos de Golpe, puedes gastar 2 de Esperanza para aumentar tu Evasión en tantos puntos como Puntos de Golpe haya marcado. El bonificador dura hasta después del siguiente ataque que reciba."},
{"id":"reapers-strike","n":"Golpe del segador","en":"Reaper’s Strike","lv":9,"d":"Blade","ty":"Ability","rc":3,"t":"Una vez por descanso largo, gasta una Esperanza para hacer una tirada de ataque. El DM te dice contra qué objetivos a tu alcance tendría éxito. Elige uno de ellos y oblígalo a marcar 5 Puntos de Golpe."},
{"id":"battle-monster","n":"Monstruo de batalla","en":"Battle Monster","lv":10,"d":"Blade","ty":"Ability","rc":0,"t":"Cuando aciertes un ataque contra un adversario, puedes marcar 4 de Estrés para obligar al objetivo a marcar tantos Puntos de Golpe como Puntos de Golpe tengas tú marcados, en lugar de tirar el daño."},
{"id":"onslaught","n":"Embestida","en":"Onslaught","lv":10,"d":"Blade","ty":"Ability","rc":3,"t":"Cuando aciertes un ataque con tu arma, nunca infliges daño por debajo del umbral Mayor del objetivo (siempre marca al menos 2 Puntos de Golpe). Además, cuando una criatura al alcance de tu arma haga daño a un aliado con un ataque que no te incluya a ti, puedes marcar un Estrés para obligarla a hacer una Tirada de Reacción (15). Si falla, debe marcar un Punto de Golpe."},
{"id":"strategic-approach","n":"Enfoque estratégico","en":"Strategic Approach","lv":2,"d":"Bone","ty":"Ability","rc":1,"t":"Tras un descanso largo, pon en esta carta tantas fichas como tu Conocimiento (mínimo 1). La primera vez que te acerques a distancia Cercana de un adversario y lo ataques, puedes gastar una ficha para elegir una de estas opciones:\n• Haces el ataque con ventaja.\n• Un aliado a distancia Cuerpo a cuerpo del adversario recupera un Estrés.\n• Sumas un d8 a tu tirada de daño.\nCuando hagas un descanso largo, quita las fichas que no hayas gastado."},
{"id":"brace","n":"Afianzarse","en":"Brace","lv":3,"d":"Bone","ty":"Ability","rc":1,"t":"Cuando marques una casilla de Armadura para reducir el daño que recibes, puedes marcar un Estrés para marcar una casilla de Armadura más."},
{"id":"tactician","n":"Táctico","en":"Tactician","lv":3,"d":"Bone","ty":"Ability","rc":1,"t":"Cuando Ayudes a un aliado, puede gastar una Esperanza para sumar a su tirada una de tus Experiencias además de tu dado de ventaja. Cuando hagas una Tirada en equipo, puedes tirar un d20 como dado de Esperanza."},
{"id":"boost","n":"Impulso","en":"Boost","lv":4,"d":"Bone","ty":"Ability","rc":1,"t":"Marca un Estrés para impulsarte en un aliado dispuesto a distancia Cercana, salir disparado por el aire y hacer un ataque aéreo contra un objetivo a distancia Lejana. Tienes ventaja en el ataque, sumas un d10 a la tirada de daño y terminas tu movimiento a distancia Cuerpo a cuerpo del objetivo."},
{"id":"redirect","n":"Desviar","en":"Redirect","lv":4,"d":"Bone","ty":"Ability","rc":1,"t":"Cuando falle un ataque contra ti hecho desde más allá de distancia Cuerpo a cuerpo, tira tantos d6 como tu Competencia. Si alguno saca un 6, puedes marcar un Estrés para desviar el ataque y que dañe a un adversario a distancia Muy Cercana."},
{"id":"know-thy-enemy","n":"Conoce a tu enemigo","en":"Know Thy Enemy","lv":5,"d":"Bone","ty":"Ability","rc":1,"t":"Cuando observes a una criatura, puedes hacer una Tirada de Instinto contra ella. Si tienes éxito, gasta una Esperanza y pide al DM uno de estos grupos de información sobre el objetivo:\n• Sus Puntos de Golpe y Estrés sin marcar.\n• Su Dificultad y sus umbrales de daño.\n• Sus tácticas y los dados de daño de su ataque normal.\n• Sus rasgos especiales y Experiencias.\nAdemás, si tienes éxito, puedes marcar un Estrés para quitar un Miedo de la reserva de Miedo del DM."},
{"id":"signature-move","n":"Movimiento característico","en":"Signature Move","lv":5,"d":"Bone","ty":"Ability","rc":1,"t":"Ponle nombre y describe tu movimiento de combate característico. Una vez por descanso, cuando lo hagas como parte de una acción, puedes tirar un d20 como dado de Esperanza. Si tienes éxito, recuperas un Estrés."},
{"id":"rapid-riposte","n":"Réplica rápida","en":"Rapid Riposte","lv":6,"d":"Bone","ty":"Ability","rc":0,"t":"Cuando falle un ataque contra ti hecho a distancia Cuerpo a cuerpo, puedes marcar un Estrés y aprovechar la ocasión para infligir al atacante el daño de una de tus armas activas."},
{"id":"recovery","n":"Recuperación","en":"Recovery","lv":6,"d":"Bone","ty":"Ability","rc":1,"t":"Durante un descanso corto, puedes elegir en su lugar un movimiento de tiempo libre de descanso largo. Puedes gastar una Esperanza para que un aliado haga lo mismo."},
{"id":"bone-touched","n":"Tocado por el Hueso","en":"Bone-Touched","lv":7,"d":"Bone","ty":"Ability","rc":2,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Hueso, obtienes estos beneficios:\n• +1 a la Agilidad.\n• Una vez por descanso, puedes gastar 3 de Esperanza para que un ataque que te había acertado falle."},
{"id":"cruel-precision","n":"Precisión cruel","en":"Cruel Precision","lv":7,"d":"Bone","ty":"Ability","rc":1,"t":"Cuando aciertes un ataque con un arma, ganas a tu tirada de daño un bonificador igual a tu Finura o a tu Agilidad."},
{"id":"breaking-blow","n":"Golpe demoledor","en":"Breaking Blow","lv":8,"d":"Bone","ty":"Ability","rc":3,"t":"Cuando aciertes un ataque, puedes marcar un Estrés para que el siguiente ataque que acierte contra ese mismo objetivo inflija 2d12 de daño extra."},
{"id":"wrangle","n":"Arrear","en":"Wrangle","lv":8,"d":"Bone","ty":"Ability","rc":1,"t":"Haz una Tirada de Agilidad contra todos los objetivos a distancia Cercana. Gasta una Esperanza para mover a los objetivos contra los que tengas éxito, y a los aliados dispuestos a distancia Cercana, a otro punto a distancia Cercana."},
{"id":"on-the-brink","n":"Al borde","en":"On the Brink","lv":9,"d":"Bone","ty":"Ability","rc":1,"t":"Cuando te queden 2 o menos Puntos de Golpe sin marcar, no recibes daño Menor."},
{"id":"splintering-strike","n":"Golpe astillador","en":"Splintering Strike","lv":9,"d":"Bone","ty":"Ability","rc":3,"t":"Gasta una Esperanza y ataca a todos los adversarios al alcance de tu arma. Una vez por descanso largo, si tienes éxito contra alguno, suma el daño infligido y repártelo como quieras entre los objetivos contra los que tuviste éxito. Cuando hagas daño a un objetivo, tira un dado de daño más y suma su resultado al daño que le haces."},
{"id":"deathrun","n":"Carrera mortal","en":"Deathrun","lv":10,"d":"Bone","ty":"Ability","rc":1,"t":"Gasta 3 de Esperanza para correr en línea recta por el campo de batalla hasta un punto a distancia Lejana, atacando a todos los adversarios que queden al alcance de tu arma en ese camino. Elige en qué orden haces daño a los objetivos contra los que tuviste éxito. Para el primero, tira el daño de tu arma con +1 a tu Competencia. Luego quita un dado de tu tirada de daño e inflige el resto al siguiente objetivo. Sigue quitando un dado por cada objetivo hasta que no te queden dados de daño o adversarios. No puedes elegir al mismo adversario más de una vez por ataque."},
{"id":"swift-step","n":"Paso veloz","en":"Swift Step","lv":10,"d":"Bone","ty":"Ability","rc":2,"t":"Cuando falle un ataque contra ti, recuperas un Estrés. Si no puedes recuperar Estrés, ganas una Esperanza."},
{"id":"book-of-ava","n":"Libro de Ava","en":"Book of Ava","lv":1,"d":"Codex","ty":"Grimoire","rc":2,"t":"Empujón de poder: Haz una Tirada de Lanzamiento contra un objetivo a distancia Cuerpo a cuerpo. Si tienes éxito, sale despedido hasta distancia Lejana y recibe d10+2 de daño mágico usando tu Competencia. Armadura de Tava: Gasta una Esperanza para dar a un objetivo al que puedas tocar +1 a su Puntuación de Armadura hasta su siguiente descanso o hasta que vuelvas a lanzar Armadura de Tava. Estaca de hielo: Haz una Tirada de Lanzamiento (12) para invocar una gran estaca de hielo a distancia Lejana. Si la usas como arma, haz la Tirada de Lanzamiento contra la Dificultad del objetivo. Si tienes éxito, inflige d6 de daño físico usando tu Competencia."},
{"id":"book-of-illiat","n":"Libro de Illiat","en":"Book of Illiat","lv":1,"d":"Codex","ty":"Grimoire","rc":2,"t":"Sopor: Haz una Tirada de Lanzamiento contra un objetivo a distancia Muy Cercana. Si tienes éxito, queda Dormido hasta que reciba daño o el DM gaste un Miedo en su turno para quitarle este estado. Andanada arcana: Una vez por descanso, gasta las Esperanzas que quieras y dispara proyectiles mágicos contra un objetivo que elijas a distancia Cercana. Tira tantos d6 como Esperanzas hayas gastado e inflige esa cantidad de daño mágico al objetivo. Telepatía: Gasta una Esperanza para abrir una línea de comunicación mental con un objetivo que puedas ver. La conexión dura hasta tu siguiente descanso o hasta que vuelvas a lanzar Telepatía."},
{"id":"book-of-tyfar","n":"Libro de Tyfar","en":"Book of Tyfar","lv":1,"d":"Codex","ty":"Grimoire","rc":2,"t":"Llama salvaje: Haz una Tirada de Lanzamiento contra hasta tres adversarios a distancia Cuerpo a cuerpo. Los objetivos contra los que tengas éxito reciben 2d6 de daño mágico y deben marcar un Estrés cuando las llamas brotan de tu mano. Mano mágica: Conjuras una mano mágica del mismo tamaño y fuerza que la tuya a distancia Lejana. Niebla misteriosa: Haz una Tirada de Lanzamiento (13) para crear una niebla espesa temporal que se acumula en una zona fija a distancia Muy Cercana. La niebla oculta casi por completo esa zona y todo lo que hay en ella."},
{"id":"book-of-sitil","n":"Libro de Sitil","en":"Book of Sitil","lv":2,"d":"Codex","ty":"Grimoire","rc":2,"t":"Cambiar apariencia: Cambias por arte de magia tu aspecto y tu ropa para que no te reconozcan. Parallela: Gasta 2 de Esperanza para lanzar este hechizo sobre ti o sobre un aliado a distancia Cercana. La próxima vez que el objetivo ataque, puede alcanzar a un objetivo adicional a su alcance contra el que su tirada de ataque tendría éxito. Solo puedes mantener este hechizo sobre una criatura a la vez. Ilusión: Haz una Tirada de Lanzamiento (14). Si tienes éxito, crea a distancia Cercana una ilusión visual temporal no más grande que tú, que dura mientras la mires. Resiste el examen hasta que un observador está a distancia Cuerpo a cuerpo."},
{"id":"book-of-vagras","n":"Libro de Vagras","en":"Book of Vagras","lv":2,"d":"Codex","ty":"Grimoire","rc":2,"t":"Cerrojo rúnico: Haz una Tirada de Lanzamiento (15) sobre un objeto que estés tocando y que se pueda cerrar (como una cerradura, un cofre o una caja). Una vez por descanso, si tienes éxito, puedes cerrarlo para que solo lo abran las criaturas que elijas. Alguien con acceso a la magia y una hora para estudiar el hechizo puede romperlo. Puerta arcana: Cuando no tengas adversarios a distancia Cuerpo a cuerpo, haz una Tirada de Lanzamiento (13). Si tienes éxito, gasta una Esperanza para crear un portal desde donde estás hasta un punto que puedas ver a distancia Lejana. Se cierra cuando una criatura lo atraviesa. Revelar: Haz una Tirada de Lanzamiento. Si hay algo oculto mediante magia a distancia Cercana, queda al descubierto."},
{"id":"book-of-korvax","n":"Libro de Korvax","en":"Book of Korvax","lv":3,"d":"Codex","ty":"Grimoire","rc":2,"t":"Levitación: Haz una Tirada de Lanzamiento para elevar en el aire de forma temporal a un objetivo que puedas ver y moverlo a distancia Cercana de donde estaba. Retractar: Gasta una Esperanza para obligar a un objetivo a distancia Cuerpo a cuerpo a hacer una Tirada de Reacción (15). Si falla, olvida el último minuto de vuestra conversación. Círculo rúnico: Marca un Estrés para crear un círculo mágico temporal en el suelo donde estás. Todos los adversarios a distancia Cuerpo a cuerpo, o que entren en ella, reciben 2d12+4 de daño mágico y salen despedidos hasta distancia Muy Cercana."},
{"id":"book-of-norai","n":"Libro de Norai","en":"Book of Norai","lv":3,"d":"Codex","ty":"Grimoire","rc":2,"t":"Atadura mística: Haz una Tirada de Lanzamiento contra un objetivo a distancia Lejana. Si tienes éxito, queda Inmovilizado de forma temporal y debe marcar un Estrés. Si el objetivo vuela, el hechizo lo hace caer al suelo y lo Inmoviliza de forma temporal. Bola de fuego: Haz una Tirada de Lanzamiento contra un objetivo a distancia Muy Lejana. Si tienes éxito, le arrojas una esfera de fuego que estalla al impactar. El objetivo y todas las criaturas a distancia Muy Cercana de él deben hacer una Tirada de Reacción (13). Los que fallen reciben d20+5 de daño mágico usando tu Competencia. Los que tengan éxito reciben la mitad del daño."},
{"id":"book-of-exota","n":"Libro de Exota","en":"Book of Exota","lv":4,"d":"Codex","ty":"Grimoire","rc":3,"t":"Repudiar: Puedes interrumpir un efecto mágico que esté ocurriendo. Haz una Tirada de Reacción con tu rasgo de Lanzamiento. Una vez por descanso, si tienes éxito, el efecto se detiene y se evitan sus consecuencias. Crear constructo: Gasta una Esperanza para elegir un grupo de objetos a tu alrededor y crear con ellos un constructo animado que obedece órdenes sencillas. Haz una Tirada de Lanzamiento para ordenarle que actúe. Cuando haga falta, comparte tu Evasión y tus rasgos, y sus ataques infligen 2d10+3 de daño físico. Solo puedes mantener un constructo a la vez, y se desmorona en cuanto recibe cualquier daño."},
{"id":"book-of-grynn","n":"Libro de Grynn","en":"Book of Grynn","lv":4,"d":"Codex","ty":"Grimoire","rc":2,"t":"Desvío arcano: Una vez por descanso largo, gasta una Esperanza para anular el daño de un ataque contra ti o contra un aliado a distancia Muy Cercana. Bloqueo temporal: Elige un objeto a distancia Lejana. Ese objeto se detiene en el tiempo y el espacio justo donde está hasta tu siguiente descanso. Si una criatura intenta moverlo, haz una Tirada de Lanzamiento contra ella para mantener el hechizo. Muro de llamas: Haz una Tirada de Lanzamiento (15). Si tienes éxito, crea un muro de llamas mágicas entre dos puntos a distancia Lejana. Las criaturas que estén en su camino deben elegir a qué lado quedarse, y todo lo que atraviese el muro después recibe 4d10+3 de daño mágico."},
{"id":"manifest-wall","n":"Muro manifiesto","en":"Manifest Wall","lv":5,"d":"Codex","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (15). Una vez por descanso, si tienes éxito, gasta una Esperanza para crear un muro mágico temporal entre dos puntos a distancia Lejana. Puede medir hasta 15 metros de alto y formarse con cualquier ángulo. Las criaturas u objetos que estén en su camino se apartan al lado que elijas. El muro aguanta hasta tu siguiente descanso o hasta que vuelvas a lanzar Muro manifiesto."},
{"id":"teleport","n":"Teletransporte","en":"Teleport","lv":5,"d":"Codex","ty":"Spell","rc":2,"t":"Una vez por descanso largo, puedes teletransportarte al instante, junto con los objetivos dispuestos que quieras a distancia Cercana, a un lugar en el que hayas estado antes. Elige una de estas opciones y haz una Tirada de Lanzamiento (16):\n• Si conoces muy bien el lugar, +3.\n• Si lo has visitado a menudo, +1.\n• Si lo has visitado pocas veces, sin modificador.\n• Si solo has estado allí una vez, −2.\nSi tienes éxito, apareces donde querías ir. Si fallas, apareces desviado, y cuanto peor el fallo, más lejos."},
{"id":"banish","n":"Destierro","en":"Banish","lv":6,"d":"Codex","ty":"Spell","rc":0,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Cercana. Si tienes éxito, tira tantos d20 como tu rasgo de Lanzamiento. El objetivo debe hacer una Tirada de Reacción con una Dificultad igual a tu resultado más alto. Si tiene éxito, debe marcar un Estrés pero no queda desterrado. Una vez por descanso, si falla, queda desterrado de este mundo. Cuando los PJs tiren con Miedo, la Dificultad baja 1 y el objetivo hace otra Tirada de Reacción. Si tiene éxito, vuelve del destierro."},
{"id":"sigil-of-retribution","n":"Sello de represalia","en":"Sigil of Retribution","lv":6,"d":"Codex","ty":"Spell","rc":2,"t":"Marca a un adversario a distancia Cercana con un sello de represalia. El DM gana un Miedo. Cuando el adversario marcado te haga daño a ti o a tus aliados, pon un d8 en esta carta. Puedes tener tantos d8 como tu nivel. Cuando aciertes un ataque contra el adversario marcado, tira los dados de esta carta, suma el total a tu tirada de daño y quítalos. El efecto termina cuando el adversario marcado es derrotado o vuelves a lanzar Sello de represalia."},
{"id":"book-of-homet","n":"Libro de Homet","en":"Book of Homet","lv":7,"d":"Codex","ty":"Grimoire","rc":0,"t":"Atravesar: Haz una Tirada de Lanzamiento (13). Una vez por descanso, si tienes éxito, tú y todas las criaturas que te estén tocando podéis atravesar un muro o una puerta a distancia Cercana. El efecto termina cuando todos están al otro lado. Puerta planar: Haz una Tirada de Lanzamiento (14). Una vez por descanso largo, si tienes éxito, abre un portal a un lugar de otra dimensión o plano de existencia en el que hayas estado antes. El portal dura hasta tu siguiente descanso."},
{"id":"codex-touched","n":"Tocado por el Códice","en":"Codex-Touched","lv":7,"d":"Codex","ty":"Ability","rc":2,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Códice, obtienes estos beneficios:\n• Puedes marcar un Estrés para sumar tu Competencia a una Tirada de Lanzamiento.\n• Una vez por descanso, puedes cambiar esta carta por cualquier carta de tu baúl sin pagar su coste de recuperación."},
{"id":"book-of-vyola","n":"Libro de Vyola","en":"Book of Vyola","lv":8,"d":"Codex","ty":"Grimoire","rc":2,"t":"Hurgar en la memoria: Haz una Tirada de Lanzamiento contra un objetivo a distancia Lejana. Si tienes éxito, miras dentro de su mente y haces una pregunta al DM. El DM describe los recuerdos del objetivo que tengan que ver con la respuesta. Claridad compartida: Una vez por descanso largo, gasta una Esperanza para elegir a dos criaturas dispuestas. Cuando una de ellas vaya a marcar Estrés, puede elegir cuál de las dos lo marca. El hechizo dura hasta su siguiente descanso."},
{"id":"safe-haven","n":"Refugio seguro","en":"Safe Haven","lv":8,"d":"Codex","ty":"Spell","rc":3,"t":"Cuando tengas unos minutos de calma para concentrarte, puedes gastar 2 de Esperanza para invocar tu Refugio seguro, una gran casa interdimensional donde tú y tus aliados podéis guareceros. Al hacerlo, aparece una puerta mágica en algún punto a distancia Cercana. Solo pueden entrar las criaturas que elijas. Una vez dentro, puedes hacer invisible la entrada. Tú y cualquiera que esté dentro podéis salir siempre. Cuando sales, hay que invocar la puerta otra vez. Cuando descanses dentro de tu Refugio seguro, puedes elegir un movimiento de tiempo libre adicional."},
{"id":"book-of-ronin","n":"Libro de Ronin","en":"Book of Ronin","lv":9,"d":"Codex","ty":"Grimoire","rc":4,"t":"Transformar: Haz una Tirada de Lanzamiento (15). Si tienes éxito, te transformas en un objeto inanimado no más grande que el doble de tu tamaño normal. Puedes seguir con esa forma hasta que recibas daño. Enervación eterna: Una vez por descanso largo, haz una Tirada de Lanzamiento contra un objetivo a distancia Cercana. Si tienes éxito, queda Vulnerable para siempre. No puede quitarse este estado de ninguna manera."},
{"id":"disintegration-wave","n":"Onda desintegradora","en":"Disintegration Wave","lv":9,"d":"Codex","ty":"Spell","rc":4,"t":"Haz una Tirada de Lanzamiento (18). Una vez por descanso largo, si tienes éxito, el DM te dice qué adversarios a distancia Lejana tienen una Dificultad de 18 o menos. Marca un Estrés por cada uno que quieras alcanzar con este hechizo. Mueren y no pueden volver a la vida de ninguna manera."},
{"id":"deft-deceiver","n":"Embaucador hábil","en":"Deft Deceiver","lv":1,"d":"Grace","ty":"Ability","rc":0,"t":"Gasta una Esperanza para tener ventaja en una tirada para engañar a alguien o hacerle creer una mentira."},
{"id":"enrapture","n":"Embelesar","en":"Enrapture","lv":1,"d":"Grace","ty":"Spell","rc":0,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Cercana. Si tienes éxito, queda Embelesado de forma temporal. Mientras está Embelesado, su atención está fija en ti: su campo de visión se estrecha y no oye más que tu voz. Una vez por descanso, si tienes éxito, puedes marcar un Estrés para obligar al objetivo Embelesado a marcar también un Estrés."},
{"id":"inspirational-words","n":"Palabras inspiradoras","en":"Inspirational Words","lv":1,"d":"Grace","ty":"Ability","rc":1,"t":"Tus palabras están llenas de poder. Tras un descanso largo, pon en esta carta tantas fichas como tu Presencia. Cuando hables con un aliado, puedes gastar una ficha de esta carta para darle uno de estos beneficios:\n• Tu aliado recupera un Estrés.\n• Tu aliado recupera un Punto de Golpe.\n• Tu aliado gana una Esperanza.\nCuando hagas un descanso largo, quita las fichas que no hayas gastado."},
{"id":"tell-no-lies","n":"No mentirás","en":"Tell No Lies","lv":2,"d":"Grace","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Muy Cercana. Si tienes éxito, no puede mentirte mientras siga a distancia Cercana, aunque no está obligado a hablar. Si le haces una pregunta y se niega a responder, debe marcar un Estrés y el efecto termina. Normalmente el objetivo no sabe que le han lanzado el hechizo hasta que le hace decir la verdad."},
{"id":"book-of-yarrow","n":"Libro de Yarrow","en":"Book of Yarrow","lv":10,"d":"Codex","ty":"Grimoire","rc":2,"t":"Detener el tiempo: Haz una Tirada de Lanzamiento (18). Si tienes éxito, el tiempo se frena hasta detenerse para todos a distancia Lejana menos para ti. Vuelve a correr la siguiente vez que hagas una Tirada de Acción contra otra criatura. Inmunidad mágica: Gasta 5 de Esperanza para volverte inmune al daño mágico hasta tu siguiente descanso."},
{"id":"transcendent-union","n":"Unión trascendente","en":"Transcendent Union","lv":10,"d":"Codex","ty":"Spell","rc":1,"t":"Una vez por descanso largo, gasta 5 de Esperanza para lanzar este hechizo sobre dos o más criaturas dispuestas. Hasta tu siguiente descanso, cuando una criatura unida vaya a marcar Estrés o Puntos de Golpe, las criaturas unidas pueden elegir quién los marca."},
{"id":"troublemaker","n":"Alborotador","en":"Troublemaker","lv":2,"d":"Grace","ty":"Ability","rc":2,"t":"Cuando provoques o te burles de un objetivo a distancia Lejana, haz una Tirada de Presencia contra él. Una vez por descanso, si tienes éxito, tira tantos d4 como tu Competencia. El objetivo debe marcar tanto Estrés como el resultado más alto."},
{"id":"hypnotic-shimmer","n":"Destello hipnótico","en":"Hypnotic Shimmer","lv":3,"d":"Grace","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra todos los adversarios que tengas delante a distancia Cercana. Una vez por descanso, si tienes éxito, creas una ilusión de colores y luces parpadeantes que deja Aturdidos de forma temporal a los objetivos contra los que tengas éxito y los obliga a marcar un Estrés. Mientras están Aturdidos, no pueden usar reacciones ni hacer ninguna otra acción hasta que se quiten este estado."},
{"id":"invisibility","n":"Invisibilidad","en":"Invisibility","lv":3,"d":"Grace","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (10). Si tienes éxito, marca un Estrés y elige volverte Invisible tú o un aliado a distancia Cuerpo a cuerpo. Una criatura Invisible no se puede ver salvo por medios mágicos, y las tiradas de ataque contra ella se hacen con desventaja. Pon en esta carta tantas fichas como tu rasgo de Lanzamiento. Cuando la criatura Invisible haga una acción, gasta una ficha de esta carta. Cuando se resuelva la acción que gasta la última ficha, el efecto termina. Solo puedes mantener la Invisibilidad sobre una criatura a la vez."},
{"id":"soothing-speech","n":"Palabras tranquilizadoras","en":"Soothing Speech","lv":4,"d":"Grace","ty":"Ability","rc":1,"t":"Durante un descanso corto, cuando te tomes el tiempo de consolar a otro personaje mientras usas en él el movimiento de tiempo libre Curar heridas, recupera un Punto de Golpe más. Al hacerlo, tú también recuperas 2 Puntos de Golpe."},
{"id":"through-your-eyes","n":"A través de tus ojos","en":"Through Your Eyes","lv":4,"d":"Grace","ty":"Spell","rc":1,"t":"Elige un objetivo a distancia Muy Lejana. Puedes ver a través de sus ojos y oír a través de sus oídos. Puedes pasar libremente de tus sentidos a los suyos hasta que lances otro hechizo o hasta tu siguiente descanso."},
{"id":"thought-delver","n":"Escrutador de mentes","en":"Thought Delver","lv":5,"d":"Grace","ty":"Spell","rc":2,"t":"Puedes asomarte a la mente de los demás. Gasta una Esperanza para leer los pensamientos superficiales y vagos de un objetivo a distancia Lejana. Haz una Tirada de Lanzamiento contra el objetivo para ahondar en pensamientos más profundos y ocultos. Si tiras con Miedo, el objetivo puede darse cuenta, a criterio del DM, de que le estás leyendo la mente."},
{"id":"words-of-discord","n":"Palabras de discordia","en":"Words of Discord","lv":5,"d":"Grace","ty":"Spell","rc":1,"t":"Susurra palabras de discordia a un adversario a distancia Cuerpo a cuerpo y haz una Tirada de Lanzamiento (13). Si tienes éxito, el objetivo debe marcar un Estrés y atacar a otro adversario en vez de a ti o a tus aliados. Cuando termina el ataque, el objetivo se da cuenta de lo que ha pasado. La siguiente vez que le lances Palabras de discordia, tienes −5 a la Tirada de Lanzamiento."},
{"id":"never-upstaged","n":"Nadie me eclipsa","en":"Never Upstaged","lv":6,"d":"Grace","ty":"Ability","rc":2,"t":"Cuando marques 1 o más Puntos de Golpe por un ataque, puedes marcar un Estrés para poner en esta carta tantas fichas como Puntos de Golpe hayas marcado. En tu siguiente ataque acertado, ganas +5 a tu tirada de daño por cada ficha de esta carta, y luego quitas todas las fichas."},
{"id":"share-the-burden","n":"Compartir la carga","en":"Share the Burden","lv":6,"d":"Grace","ty":"Spell","rc":0,"t":"Una vez por descanso, asume el Estrés de una criatura dispuesta a distancia Cuerpo a cuerpo. El objetivo describe qué conocimientos íntimos o emociones se filtran telepáticamente de su mente a la tuya en ese momento. Pasa a ti el Estrés marcado que quieras de esa criatura, y gana una Esperanza por cada Estrés que pases."},
{"id":"endless-charisma","n":"Carisma sin fin","en":"Endless Charisma","lv":7,"d":"Grace","ty":"Ability","rc":1,"t":"Después de hacer una Tirada de Acción para convencer, mentir o ganarte el favor de alguien, puedes gastar una Esperanza para repetir el dado de Esperanza o el de Miedo."},
{"id":"grace-touched","n":"Tocado por la Gracia","en":"Grace-Touched","lv":7,"d":"Grace","ty":"Ability","rc":2,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Gracia, obtienes estos beneficios:\n• Puedes marcar una casilla de Armadura en lugar de marcar un Estrés.\n• Cuando fueras a obligar a un objetivo a marcar Puntos de Golpe, puedes obligarlo en su lugar a marcar esa misma cantidad de Estrés."},
{"id":"astral-projection","n":"Proyección astral","en":"Astral Projection","lv":8,"d":"Grace","ty":"Spell","rc":0,"t":"Una vez por descanso largo, marca un Estrés para crear una copia proyectada de ti que puede aparecer en cualquier lugar en el que hayas estado antes. Puedes ver y oír a través de la proyección como si fueras tú y afectar al mundo como si estuvieras allí. Una criatura que examine la proyección puede notar que es de origen mágico. El efecto dura hasta tu siguiente descanso o hasta que la proyección reciba cualquier daño."},
{"id":"mass-enrapture","n":"Embeleso en masa","en":"Mass Enrapture","lv":8,"d":"Grace","ty":"Spell","rc":3,"t":"Haz una Tirada de Lanzamiento contra todos los objetivos a distancia Lejana. Los objetivos contra los que tengas éxito quedan Embelesados de forma temporal. Mientras está Embelesado, la atención del objetivo está fija en ti: su campo de visión se estrecha y no oye más que tu voz. Marca un Estrés para obligar a todos los objetivos Embelesados a marcar un Estrés; con ello el hechizo termina."},
{"id":"copycat","n":"Imitador","en":"Copycat","lv":9,"d":"Grace","ty":"Spell","rc":3,"t":"Una vez por descanso largo, esta carta puede imitar los efectos de otra carta de dominio de nivel 8 o menos que esté en la mano de otro jugador. Gasta tanta Esperanza como la mitad del nivel de esa carta para usar su efecto. Dura hasta tu siguiente descanso o hasta que esa persona ponga la carta en su baúl."},
{"id":"master-of-the-craft","n":"Maestro del oficio","en":"Master of the Craft","lv":9,"d":"Grace","ty":"Ability","rc":0,"t":"Ganas para siempre +2 a dos de tus Experiencias o +3 a una de ellas. Después, pon esta carta en tu baúl para siempre."},
{"id":"encore","n":"Bis","en":"Encore","lv":10,"d":"Grace","ty":"Spell","rc":1,"t":"Cuando un aliado a distancia Cercana haga daño a un adversario, puedes hacer una Tirada de Lanzamiento contra ese mismo objetivo. Si tienes éxito, le haces el mismo daño que tu aliado. Si tu Tirada de Lanzamiento tiene éxito con Miedo, pon esta carta en tu baúl."},
{"id":"notorious","n":"Famoso","en":"Notorious","lv":10,"d":"Grace","ty":"Ability","rc":0,"t":"La gente sabe quién eres y lo que has hecho, y te trata distinto por ello. Cuando uses tu fama para conseguir lo que quieres, puedes marcar un Estrés antes de tirar para ganar +10 al resultado. Comes y bebes gratis vayas donde vayas, y todo lo demás que compres te cuesta una bolsa de oro menos (como mínimo, un puñado). Esta carta no cuenta para el máximo de 5 cartas de dominio de tu mano y no se puede poner en el baúl."},
{"id":"pick-and-pull","n":"Ganzúa y tirón","en":"Pick and Pull","lv":1,"d":"Midnight","ty":"Ability","rc":0,"t":"Tienes ventaja en las Tiradas de Acción para forzar cerraduras no mágicas, desactivar trampas no mágicas o robar objetos a un objetivo (con sigilo o por la fuerza)."},
{"id":"rain-of-blades","n":"Lluvia de cuchillas","en":"Rain of Blades","lv":1,"d":"Midnight","ty":"Spell","rc":1,"t":"Gasta una Esperanza para hacer una Tirada de Lanzamiento y conjurar cuchillas arrojadizas que golpean a todos los objetivos a distancia Muy Cercana. Los objetivos contra los que tengas éxito reciben d8+2 de daño mágico usando tu Competencia. Si un objetivo alcanzado está Vulnerable, recibe 1d8 de daño extra."},
{"id":"uncanny-disguise","n":"Disfraz asombroso","en":"Uncanny Disguise","lv":1,"d":"Midnight","ty":"Spell","rc":0,"t":"Cuando tengas unos minutos para prepararte, puedes marcar un Estrés para adoptar el aspecto de cualquier humanoide que puedas imaginar con claridad. Mientras vas disfrazado, tienes ventaja en las Tiradas de Presencia para no levantar sospechas. Pon en esta carta tantas fichas como tu rasgo de Lanzamiento. Cuando hagas una acción disfrazado, gasta una ficha de esta carta. Cuando se resuelva la acción que gasta la última ficha, el disfraz desaparece."},
{"id":"midnight-spirit","n":"Espíritu de medianoche","en":"Midnight Spirit","lv":2,"d":"Midnight","ty":"Spell","rc":1,"t":"Gasta una Esperanza para invocar un espíritu del tamaño de un humanoide que puede moverte o llevarte cosas hasta tu siguiente descanso. También puedes mandarlo a atacar a un adversario. Si lo haces, haz una Tirada de Lanzamiento contra un objetivo a distancia Muy Lejana. Si tienes éxito, el espíritu se pone a distancia Cuerpo a cuerpo de ese objetivo. Tira tantos d6 como tu rasgo de Lanzamiento e inflige esa cantidad de daño mágico al objetivo. Después, el espíritu se desvanece. Solo puedes tener un espíritu a la vez."},
{"id":"shadowbind","n":"Atadura de sombras","en":"Shadowbind","lv":2,"d":"Midnight","ty":"Spell","rc":0,"t":"Haz una Tirada de Lanzamiento contra todos los adversarios a distancia Muy Cercana. Los objetivos contra los que tengas éxito quedan Inmovilizados de forma temporal, atados por su propia sombra."},
{"id":"chokehold","n":"Estrangulamiento","en":"Chokehold","lv":3,"d":"Midnight","ty":"Ability","rc":1,"t":"Cuando te pongas detrás de una criatura de un tamaño parecido al tuyo, puedes marcar un Estrés para hacerle una llave de estrangulamiento que la deja Vulnerable de forma temporal. Cuando una criatura ataque a un objetivo que esté Vulnerable de esta manera, le hace 2d6 de daño extra."},
{"id":"veil-of-night","n":"Velo de la noche","en":"Veil of Night","lv":3,"d":"Midnight","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (13). Si tienes éxito, puedes crear una cortina de oscuridad temporal entre dos puntos a distancia Lejana. Solo tú puedes ver a través de ella. Para los adversarios del otro lado del velo estás Oculto, y tienes ventaja en los ataques que hagas a través de la oscuridad. El velo dura hasta que lances otro hechizo."},
{"id":"stealth-expertise","n":"Experto en sigilo","en":"Stealth Expertise","lv":4,"d":"Midnight","ty":"Ability","rc":0,"t":"Cuando tires con Miedo al intentar pasar desapercibido por una zona peligrosa, puedes marcar un Estrés para tirar con Esperanza en su lugar. Si un aliado a distancia Cercana también intenta pasar desapercibido y tira con Miedo, puedes marcar un Estrés para cambiar su resultado a una tirada con Esperanza."},
{"id":"glyph-of-nightfall","n":"Glifo del anochecer","en":"Glyph of Nightfall","lv":4,"d":"Midnight","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Muy Cercana. Si tienes éxito, gasta una Esperanza para dibujar sobre su cuerpo un glifo oscuro que deja a la vista sus puntos débiles: su Dificultad baja de forma temporal tanto como tu Conocimiento (mínimo 1)."},
{"id":"hush","n":"Silencio","en":"Hush","lv":5,"d":"Midnight","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Cercana. Si tienes éxito, gasta una Esperanza para crear a su alrededor una magia de supresión que abarca todo lo que esté a distancia Muy Cercana de él y lo sigue cuando se mueve. El objetivo y todo lo que haya en esa zona quedan Silenciados hasta que el DM gaste un Miedo en su turno para quitar este estado, vuelvas a lanzar Silencio o recibas daño Mayor. Mientras están Silenciados, no pueden hacer ruido ni lanzar hechizos."},
{"id":"phantom-retreat","n":"Retirada fantasma","en":"Phantom Retreat","lv":5,"d":"Midnight","ty":"Spell","rc":2,"t":"Gasta una Esperanza para activar Retirada fantasma donde estás. Gasta otra Esperanza en cualquier momento antes de tu siguiente descanso para desaparecer de donde estés y reaparecer donde estabas al activarla. El hechizo termina cuando reapareces."},
{"id":"dark-whispers","n":"Susurros oscuros","en":"Dark Whispers","lv":6,"d":"Midnight","ty":"Spell","rc":0,"t":"Puedes hablar dentro de la mente de cualquier persona con la que hayas tenido contacto físico. Una vez abierto el canal, ella también puede hablar dentro de la tuya. Además, puedes marcar un Estrés para hacer una Tirada de Lanzamiento contra ella. Si tienes éxito, puedes hacerle al DM una de estas preguntas y recibir respuesta:\n• ¿Dónde está?\n• ¿Qué está haciendo?\n• ¿A qué tiene miedo?\n• ¿Qué es lo que más quiere en el mundo?"},
{"id":"mass-disguise","n":"Disfraz en masa","en":"Mass Disguise","lv":6,"d":"Midnight","ty":"Spell","rc":0,"t":"Cuando tengas unos minutos de silencio para concentrarte, puedes marcar un Estrés para cambiar el aspecto de todas las criaturas dispuestas a distancia Cercana. Sus nuevas formas deben conservar más o menos su estructura corporal y su tamaño, y pueden ser alguien o algo que hayas visto antes o algo inventado del todo. Una criatura disfrazada tiene ventaja en las Tiradas de Presencia para no levantar sospechas. Activa una Cuenta atrás (8). Baja como consecuencia que elige el DM. Cuando llega a cero, el disfraz desaparece."},
{"id":"midnight-touched","n":"Tocado por la Medianoche","en":"Midnight-Touched","lv":7,"d":"Midnight","ty":"Ability","rc":2,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Medianoche, obtienes estos beneficios:\n• Una vez por descanso, cuando tengas 0 de Esperanza y el DM vaya a ganar un Miedo, puedes ganar tú una Esperanza en su lugar.\n• Cuando aciertes un ataque, puedes marcar un Estrés para sumar el resultado de tu dado de Miedo a tu tirada de daño."},
{"id":"vanishing-dodge","n":"Esquiva evanescente","en":"Vanishing Dodge","lv":7,"d":"Midnight","ty":"Spell","rc":1,"t":"Cuando falle un ataque contra ti que haría daño físico, puedes gastar una Esperanza para envolverte en sombras: quedas Oculto y te teletransportas a un punto a distancia Cercana del atacante. Sigues Oculto hasta la siguiente vez que hagas una Tirada de Acción."},
{"id":"shadowhunter","n":"Cazador de sombras","en":"Shadowhunter","lv":8,"d":"Midnight","ty":"Ability","rc":2,"t":"Tu destreza aumenta al amparo de las sombras. Mientras estés en penumbra u oscuridad, ganas +1 a tu Evasión y haces las tiradas de ataque con ventaja."},
{"id":"spellcharge","n":"Carga de hechizos","en":"Spellcharge","lv":8,"d":"Midnight","ty":"Spell","rc":1,"t":"Cuando recibas daño mágico, pon en esta carta tantas fichas como Puntos de Golpe hayas marcado. Puedes guardar tantas fichas como tu rasgo de Lanzamiento. Cuando aciertes un ataque contra un objetivo, puedes gastar las fichas que quieras para sumar un d6 por ficha a tu tirada de daño."},
{"id":"night-terror","n":"Terror nocturno","en":"Night Terror","lv":9,"d":"Midnight","ty":"Spell","rc":2,"t":"Una vez por descanso largo, elige los objetivos que quieras a distancia Muy Cercana para que te vean como un horror de pesadilla. Deben superar una Tirada de Reacción (16) o quedar Horrorizados de forma temporal. Mientras están Horrorizados, son Vulnerables. Roba al DM tantos Miedos como objetivos Horrorizados (como mucho, los que tenga en su reserva). Tira tantos d6 como Miedos robados e inflige el total a cada objetivo Horrorizado. Descarta los Miedos robados."},
{"id":"twilight-toll","n":"Tañido del ocaso","en":"Twilight Toll","lv":9,"d":"Midnight","ty":"Ability","rc":1,"t":"Elige un objetivo a distancia Lejana. Cuando tengas éxito en una Tirada de Acción contra él que no lleve a una tirada de daño, pon una ficha en esta carta. Cuando hagas daño a ese objetivo, gasta las fichas que quieras para sumar un d12 por ficha a tu tirada de daño. Solo puedes mantener Tañido del ocaso sobre una criatura a la vez. Cuando elijas un objetivo nuevo o descanses, quita las fichas que no hayas gastado."},
{"id":"eclipse","n":"Eclipse","en":"Eclipse","lv":10,"d":"Midnight","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (16). Una vez por descanso largo, si tienes éxito, sumerge toda la zona a distancia Lejana en una oscuridad total a través de la cual solo ves tú y tus aliados. Las tiradas de ataque contra ti o contra un aliado dentro de esta sombra tienen desventaja. Además, cuando tú o un aliado tengáis éxito con Esperanza contra un adversario dentro de la sombra, el objetivo debe marcar un Estrés. El hechizo dura hasta que el DM gaste un Miedo en su turno para quitar el efecto o recibas daño Grave."},
{"id":"specter-of-the-dark","n":"Espectro de la oscuridad","en":"Specter of the Dark","lv":10,"d":"Midnight","ty":"Spell","rc":1,"t":"Marca un Estrés para volverte Espectral hasta que hagas una Tirada de Acción contra otra criatura. Mientras eres Espectral, eres inmune al daño físico y puedes flotar y atravesar objetos sólidos. Las demás criaturas siguen viéndote con esta forma."},
{"id":"gifted-tracker","n":"Rastreador dotado","en":"Gifted Tracker","lv":1,"d":"Sage","ty":"Ability","rc":0,"t":"Cuando sigas el rastro de una criatura o un grupo concreto por las señales de su paso, puedes gastar las Esperanzas que quieras y hacer al DM esa cantidad de preguntas de esta lista:\n• ¿Hacia dónde fueron?\n• ¿Cuánto hace que pasaron?\n• ¿Qué hacían en este lugar?\n• ¿Cuántos había aquí?\nCuando te encuentres con criaturas a las que hayas rastreado así, ganas +1 a tu Evasión contra ellas."},
{"id":"natures-tongue","n":"Lengua de la naturaleza","en":"Nature’s Tongue","lv":1,"d":"Sage","ty":"Ability","rc":0,"t":"Puedes hablar el idioma del mundo natural. Cuando quieras hablar con las plantas y los animales que te rodean, haz una Tirada de Instinto (12). Si tienes éxito, te darán la información que sepan. Si tiras con Miedo, puede que sepan poco o que te cueste algo. Además, antes de hacer una Tirada de Lanzamiento en un entorno natural, puedes gastar una Esperanza para ganar +2 a la tirada."},
{"id":"vicious-entangle","n":"Enredo feroz","en":"Vicious Entangle","lv":1,"d":"Sage","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Lejana. Si tienes éxito, raíces y enredaderas brotan del suelo, le hacen 1d8+1 de daño físico y lo Inmovilizan de forma temporal. Además, si tienes éxito, puedes gastar una Esperanza para Inmovilizar de forma temporal a otro adversario a distancia Muy Cercana de tu objetivo."},
{"id":"conjure-swarm","n":"Conjurar enjambre","en":"Conjure Swarm","lv":2,"d":"Sage","ty":"Spell","rc":1,"t":"Escarabajos acorazados de Tekaira: Marca un Estrés para conjurar escarabajos acorazados que te rodean. La próxima vez que recibas daño, reduce la gravedad un umbral. Puedes gastar una Esperanza para que los escarabajos sigan contigo después de recibir el daño. Luciérnagas de fuego: Haz una Tirada de Lanzamiento contra todos los adversarios a distancia Cercana. Gasta una Esperanza para infligir 2d8+3 de daño mágico a los objetivos contra los que tuviste éxito."},
{"id":"natural-familiar","n":"Familiar natural","en":"Natural Familiar","lv":2,"d":"Sage","ty":"Spell","rc":1,"t":"Gasta una Esperanza para invocar a tu lado un pequeño espíritu de la naturaleza o un animalillo del bosque hasta tu siguiente descanso, hasta que vuelvas a lanzar Familiar natural o hasta que el familiar sea objetivo de un ataque. Si gastas una Esperanza más, puedes invocar un familiar que vuela. Puedes comunicarte con él, hacer una Tirada de Lanzamiento para mandarle tareas sencillas y marcar un Estrés para ver a través de sus ojos. Cuando hagas daño a un adversario a distancia Cuerpo a cuerpo de tu familiar, sumas un d6 a tu tirada de daño."},
{"id":"corrosive-projectile","n":"Proyectil corrosivo","en":"Corrosive Projectile","lv":3,"d":"Sage","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Lejana. Si tienes éxito, inflige d6+4 de daño mágico usando tu Competencia. Además, marca 2 o más de Estrés para dejarlo Corroído para siempre. Mientras un objetivo está Corroído, su Dificultad baja 1 por cada 2 de Estrés que gastaste. Este estado se acumula."},
{"id":"towering-stalk","n":"Tallo gigante","en":"Towering Stalk","lv":3,"d":"Sage","ty":"Spell","rc":1,"t":"Una vez por descanso, puedes conjurar a distancia Cercana un tallo grueso y retorcido por el que es fácil trepar. Puede crecer hasta distancia Lejana de alto. Marca un Estrés para usar este hechizo como ataque. Haz una Tirada de Lanzamiento contra un adversario o un grupo de adversarios a distancia Cercana. El tallo, al brotar, levanta por los aires a los objetivos contra los que tengas éxito y los deja caer, haciéndoles d8 de daño físico usando tu Competencia."},
{"id":"death-grip","n":"Presa mortal","en":"Death Grip","lv":4,"d":"Sage","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Cercana y elige una de estas opciones:\n• Atraes al objetivo hasta distancia Cuerpo a cuerpo o te acercas tú a distancia Cuerpo a cuerpo de él.\n• Aprietas al objetivo y lo obligas a marcar 2 de Estrés.\n• Todos los adversarios entre tú y el objetivo deben superar una Tirada de Reacción (13) o los golpean las enredaderas, recibiendo 3d6+2 de daño físico.\nSi tienes éxito, brotan enredaderas de tus manos que causan el efecto elegido e Inmovilizan al objetivo de forma temporal."},
{"id":"healing-field","n":"Campo sanador","en":"Healing Field","lv":4,"d":"Sage","ty":"Spell","rc":2,"t":"Una vez por descanso largo, puedes conjurar a tu alrededor un campo de plantas sanadoras. Todo lo que está a distancia Cercana de ti estalla de vida, y tú y todos los aliados de la zona recuperáis un Punto de Golpe. Gasta 2 de Esperanza para que tú y todos tus aliados recuperéis 2 Puntos de Golpe en su lugar."},
{"id":"thorn-skin","n":"Piel de espinas","en":"Thorn Skin","lv":5,"d":"Sage","ty":"Spell","rc":1,"t":"Una vez por descanso, gasta una Esperanza para que te broten espinas por todo el cuerpo. Al hacerlo, pon en esta carta tantas fichas como tu rasgo de Lanzamiento. Cuando recibas daño, puedes gastar las fichas que quieras para tirar esa cantidad de d6. Suma los resultados y reduce en esa cantidad el daño que recibes. Si estás a distancia Cuerpo a cuerpo del atacante, le haces esa misma cantidad de daño. Cuando descanses, quita las fichas que no hayas gastado."},
{"id":"wild-fortress","n":"Fortaleza salvaje","en":"Wild Fortress","lv":5,"d":"Sage","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (13). Si tienes éxito, gasta 2 de Esperanza para hacer crecer una barricada natural en forma de cúpula en la que tú y un aliado podéis poneros a cubierto. Dentro de la cúpula, una criatura no puede ser objetivo de ataques ni atacar. Los ataques contra la cúpula aciertan siempre. La cúpula tiene estos umbrales de daño y dura hasta que marque 3 Puntos de Golpe. Pon fichas en esta carta para contar los Puntos de Golpe marcados. Umbrales: 15/30"},
{"id":"conjured-steeds","n":"Monturas conjuradas","en":"Conjured Steeds","lv":6,"d":"Sage","ty":"Spell","rc":0,"t":"Gasta las Esperanzas que quieras para conjurar esa cantidad de monturas mágicas (como caballos, camellos o elefantes) que tú y tus aliados podéis montar hasta vuestro siguiente descanso largo o hasta que las monturas reciban cualquier daño. Las monturas doblan vuestra velocidad por tierra al viajar y, en peligro, os dejan moveros a distancia Lejana sin tirar. Las criaturas que montan tienen −2 a las tiradas de ataque y +2 a las tiradas de daño."},
{"id":"forager","n":"Recolector","en":"Forager","lv":6,"d":"Sage","ty":"Ability","rc":1,"t":"Como movimiento de tiempo libre adicional que puedes elegir, tira un d6 para ver qué encuentras. Descríbelo junto con el DM y añádelo a tu inventario como consumible. Tu grupo puede llevar hasta cinco consumibles recolectados a la vez.\n1. Un alimento único (recupera 2 de Estrés).\n2. Una reliquia preciosa (gana 2 de Esperanza).\n3. Una runa arcana (+2 a una Tirada de Lanzamiento).\n4. Un vial curativo (recupera 2 Puntos de Golpe).\n5. Un amuleto de la suerte (repite cualquier dado).\n6. Elige una de las opciones anteriores."},
{"id":"sage-touched","n":"Tocado por el Sabio","en":"Sage-Touched","lv":7,"d":"Sage","ty":"Ability","rc":2,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Sabio, obtienes estos beneficios:\n• Mientras estés en un entorno natural, ganas +2 a tus Tiradas de Lanzamiento.\n• Una vez por descanso, puedes doblar tu Agilidad o tu Instinto al hacer una tirada con ese rasgo. Tienes que decidirlo antes de tirar."},
{"id":"wild-surge","n":"Oleada salvaje","en":"Wild Surge","lv":7,"d":"Sage","ty":"Spell","rc":2,"t":"Una vez por descanso largo, marca un Estrés para canalizar el mundo natural que te rodea y potenciarte. Describe cómo cambia tu aspecto y pon un d6 en esta carta con el 1 hacia arriba. Mientras el dado de Oleada salvaje esté activo, sumas su valor a todas tus Tiradas de Acción. Después de sumar su valor a una tirada, sube el dado en uno. Cuando el dado fuera a pasar de 6 o descanses, pierdes esta forma y debes marcar un Estrés más."},
{"id":"forest-sprites","n":"Duendes del bosque","en":"Forest Sprites","lv":8,"d":"Sage","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (13). Si tienes éxito, gasta las Esperanzas que quieras para crear esa misma cantidad de pequeños duendes del bosque, que aparecen en los puntos que elijas a distancia Lejana y dan estos beneficios:\n• Tus aliados ganan +3 a las tiradas de ataque contra adversarios a distancia Cuerpo a cuerpo de un duende.\n• Un aliado que marque una casilla de Armadura a distancia Cuerpo a cuerpo de un duende puede marcar una casilla de Armadura más.\nUn duende desaparece después de dar un beneficio o de recibir cualquier daño."},
{"id":"rejuvenation-barrier","n":"Barrera rejuvenecedora","en":"Rejuvenation Barrier","lv":8,"d":"Sage","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (15). Una vez por descanso, si tienes éxito, crea a tu alrededor, a distancia Muy Cercana, una barrera temporal de energía protectora. Tú y todos los aliados que estén dentro al lanzar el hechizo recuperáis 1d4 Puntos de Golpe. Mientras la barrera esté levantada, tú y los aliados que estén dentro tenéis resistencia al daño físico que venga de fuera. Cuando te mueves, la barrera te sigue."},
{"id":"fane-of-the-wilds","n":"Santuario de lo salvaje","en":"Fane of the Wilds","lv":9,"d":"Sage","ty":"Ability","rc":2,"t":"Tras un descanso largo, pon en esta carta tantas fichas como cartas del dominio Sabio tengas en tu mano y tu baúl. Cuando vayas a hacer una Tirada de Lanzamiento, puedes gastar las fichas que quieras después de tirar para ganar +1 por ficha. Cuando consigas un éxito crítico en una Tirada de Lanzamiento de un hechizo del dominio Sabio, ganas una ficha. Cuando hagas un descanso largo, quita las fichas que no hayas gastado."},
{"id":"plant-dominion","n":"Dominio vegetal","en":"Plant Dominion","lv":9,"d":"Sage","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (18). Una vez por descanso largo, si tienes éxito, das nueva forma al mundo natural y cambias las plantas de tu alrededor en cualquier punto a distancia Lejana. Por ejemplo, puedes hacer crecer árboles al instante, abrir camino entre enredaderas espesas o levantar un muro de raíces."},
{"id":"force-of-nature","n":"Fuerza de la naturaleza","en":"Force of Nature","lv":10,"d":"Sage","ty":"Spell","rc":2,"t":"Marca un Estrés para transformarte en un enorme espíritu de la naturaleza y obtener estos beneficios:\n• Cuando tengas éxito en un ataque o una Tirada de Lanzamiento, ganas +10 a la tirada de daño.\n• Cuando inflijas daño suficiente para derrotar a una criatura a distancia Cercana, la absorbes y recuperas una casilla de Armadura.\n• No pueden Inmovilizarte.\nAntes de hacer una Tirada de Acción, debes gastar una Esperanza. Si no puedes, vuelves a tu forma normal."},
{"id":"tempest","n":"Tempestad","en":"Tempest","lv":10,"d":"Sage","ty":"Spell","rc":2,"t":"Elige una de estas tempestades y haz una Tirada de Lanzamiento contra todos los objetivos a distancia Lejana. Los objetivos contra los que tengas éxito sufren sus efectos hasta que el DM gaste un Miedo en su turno para terminar el hechizo.\n• Ventisca: Inflige 2d20+8 de daño mágico y los objetivos quedan Vulnerables de forma temporal.\n• Huracán: Inflige 3d10+10 de daño mágico y elige hacia dónde sopla el viento. Los objetivos no pueden moverse contra el viento.\n• Tormenta de arena: Inflige 5d6+9 de daño mágico. Los ataques hechos desde más allá de distancia Cuerpo a cuerpo tienen desventaja."},
{"id":"bolt-beacon","n":"Faro de rayos","en":"Bolt Beacon","lv":1,"d":"Splendor","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento contra un objetivo a distancia Lejana. Si tienes éxito, gasta una Esperanza para lanzarle un rayo de luz resplandeciente que le hace d8+2 de daño mágico usando tu Competencia. El objetivo queda Vulnerable de forma temporal y brilla con fuerza hasta que se le quite este estado."},
{"id":"mending-touch","n":"Toque reparador","en":"Mending Touch","lv":1,"d":"Splendor","ty":"Spell","rc":1,"t":"Pones las manos sobre una criatura y canalizas magia curativa para cerrar sus heridas. Cuando puedas dedicar unos minutos a centrarte en ella, puedes gastar 2 de Esperanza para que recupere un Punto de Golpe o un Estrés. Una vez por descanso largo, si dedicas ese rato a descubrir algo nuevo de ella o a contarle algo de ti, puede recuperar 2 Puntos de Golpe o 2 de Estrés en su lugar."},
{"id":"reassurance","n":"Ánimo","en":"Reassurance","lv":1,"d":"Splendor","ty":"Ability","rc":0,"t":"Una vez por descanso, después de que un aliado intente una Tirada de Acción pero antes de que se apliquen las consecuencias, puedes ofrecerle ayuda o palabras de apoyo. Si lo haces, tu aliado puede repetir sus dados."},
{"id":"final-words","n":"Últimas palabras","en":"Final Words","lv":2,"d":"Splendor","ty":"Spell","rc":1,"t":"Puedes infundir en un cadáver un instante de vida para hablar con él. Haz una Tirada de Lanzamiento (13). Si tienes éxito con Esperanza, el cadáver responde hasta tres preguntas. Si tienes éxito con Miedo, responde una. El cadáver dice la verdad, pero no puede contar nada que no supiera en vida. Si fallas, o cuando termina de responder, el cuerpo se convierte en polvo."},
{"id":"healing-hands","n":"Manos sanadoras","en":"Healing Hands","lv":2,"d":"Splendor","ty":"Spell","rc":1,"t":"Haz una Tirada de Lanzamiento (13) eligiendo como objetivo a una criatura que no seas tú a distancia Cuerpo a cuerpo. Si tienes éxito, marca un Estrés para que el objetivo recupere 2 Puntos de Golpe o 2 de Estrés. Si fallas, marca un Estrés para que recupere un Punto de Golpe o un Estrés. No puedes volver a curar al mismo objetivo hasta tu siguiente descanso largo."},
{"id":"second-wind","n":"Segundo aliento","en":"Second Wind","lv":3,"d":"Splendor","ty":"Ability","rc":2,"t":"Una vez por descanso, cuando aciertes un ataque contra un adversario, puedes recuperar 3 de Estrés o un Punto de Golpe. Si tienes éxito con Esperanza, un aliado a distancia Cercana de ti también recupera 3 de Estrés o un Punto de Golpe."},
{"id":"voice-of-reason","n":"Voz de la razón","en":"Voice of Reason","lv":3,"d":"Splendor","ty":"Ability","rc":1,"t":"Hablas con un poder y una autoridad sin igual. Tienes ventaja en las Tiradas de Acción para calmar situaciones violentas o convencer a alguien de que te siga. Además, la presión te crece. Cuando tengas marcadas todas tus casillas de Estrés, ganas +1 a tu Competencia en las tiradas de daño."},
{"id":"divination","n":"Adivinación","en":"Divination","lv":4,"d":"Splendor","ty":"Spell","rc":1,"t":"Una vez por descanso largo, gasta 3 de Esperanza para contactar con las fuerzas del más allá y hacer una pregunta de «sí o no» sobre un suceso, una persona, un lugar o una situación del futuro cercano. Por un momento, el presente se desvanece y ves la respuesta ante ti."},
{"id":"life-ward","n":"Guarda de vida","en":"Life Ward","lv":4,"d":"Splendor","ty":"Spell","rc":1,"t":"Gasta 3 de Esperanza y elige a un aliado a distancia Cercana. Queda marcado con un sello brillante de protección. Cuando ese aliado fuera a hacer un Movimiento de Muerte, recupera un Punto de Golpe en su lugar. El efecto termina cuando salva al objetivo de un Movimiento de Muerte, lanzas Guarda de vida sobre otro objetivo o haces un descanso largo."},
{"id":"shape-material","n":"Moldear materia","en":"Shape Material","lv":5,"d":"Splendor","ty":"Spell","rc":1,"t":"Gasta una Esperanza para dar a una porción de material natural que estés tocando (como piedra, hielo o madera) la forma que necesites. La zona de material no puede ser más grande que tú. Por ejemplo, puedes hacer una herramienta rudimentaria o abrir una puerta. Solo puedes afectar al material que esté a distancia Cercana de donde lo tocas."},
{"id":"smite","n":"Castigo","en":"Smite","lv":5,"d":"Splendor","ty":"Spell","rc":2,"t":"Una vez por descanso, gasta 3 de Esperanza para cargar tu castigo. La próxima vez que aciertes un ataque con un arma, dobla el resultado de tu tirada de daño. Este ataque hace daño mágico, sea cual sea el tipo de daño del arma."},
{"id":"restoration","n":"Restauración","en":"Restoration","lv":6,"d":"Splendor","ty":"Spell","rc":2,"t":"Tras un descanso largo, pon en esta carta tantas fichas como tu rasgo de Lanzamiento. Toca a una criatura y gasta las fichas que quieras para que recupere 2 Puntos de Golpe o 2 de Estrés por ficha. También puedes gastar una ficha al tocar a una criatura para quitarle el estado Vulnerable o curarle un mal físico o mágico (el DM puede pedir más fichas según lo fuerte que sea). Cuando hagas un descanso largo, quita las fichas que no hayas gastado."},
{"id":"zone-of-protection","n":"Zona de protección","en":"Zone of Protection","lv":6,"d":"Splendor","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (16). Una vez por descanso largo, si tienes éxito, elige un punto a distancia Lejana y crea allí una zona de protección visible para todos los aliados a distancia Muy Cercana de ese punto. Al hacerlo, pon un d6 en esta carta con el 1 hacia arriba. Cuando un aliado de la zona reciba daño, lo reduce en el valor del dado. Después, sube el dado en uno. Cuando el dado fuera a pasar de 6, el efecto termina."},
{"id":"healing-strike","n":"Golpe sanador","en":"Healing Strike","lv":7,"d":"Splendor","ty":"Spell","rc":1,"t":"Cuando hagas daño a un adversario, puedes gastar 2 de Esperanza para que un aliado a distancia Cercana recupere un Punto de Golpe."},
{"id":"splendor-touched","n":"Tocado por el Esplendor","en":"Splendor-Touched","lv":7,"d":"Splendor","ty":"Ability","rc":2,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Esplendor, obtienes estos beneficios:\n• +3 a tu umbral de daño Grave.\n• Una vez por descanso largo, cuando un daño te obligue a marcar Puntos de Golpe, puedes elegir marcar esa misma cantidad de Estrés o gastar esa misma cantidad de Esperanza en su lugar."},
{"id":"shield-aura","n":"Aura escudo","en":"Shield Aura","lv":8,"d":"Splendor","ty":"Spell","rc":2,"t":"Marca un Estrés para lanzar un aura protectora sobre un objetivo a distancia Muy Cercana. Cuando el objetivo marque una casilla de Armadura, reduce la gravedad del ataque un umbral más. Si gracias a este hechizo una criatura que iba a recibir daño no marca ningún Punto de Golpe, el efecto termina. Solo puedes mantener el Aura escudo sobre una criatura a la vez."},
{"id":"stunning-sunlight","n":"Luz solar cegadora","en":"Stunning Sunlight","lv":8,"d":"Splendor","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento para desatar poderosos rayos de sol abrasador contra todos los adversarios que tengas delante a distancia Lejana. Si tienes éxito, gasta las Esperanzas que quieras y obliga a esa cantidad de objetivos contra los que tuviste éxito a hacer una Tirada de Reacción (14). Los que tengan éxito reciben 3d20+3 de daño mágico. Los que fallen reciben 4d20+5 de daño mágico y quedan Aturdidos de forma temporal. Mientras están Aturdidos, no pueden usar reacciones ni hacer ninguna otra acción hasta que se quiten este estado."},
{"id":"overwhelming-aura","n":"Aura abrumadora","en":"Overwhelming Aura","lv":9,"d":"Splendor","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (15) para potenciar tu aura con magia. Si tienes éxito, gasta 2 de Esperanza para que tu Presencia sea igual a tu rasgo de Lanzamiento hasta tu siguiente descanso largo. Mientras dure el hechizo, un adversario debe marcar un Estrés cuando te ataque."},
{"id":"salvation-beam","n":"Rayo de salvación","en":"Salvation Beam","lv":9,"d":"Splendor","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (16). Si tienes éxito, marca el Estrés que quieras para elegir una fila de aliados a distancia Lejana. Recuperan tantos Puntos de Golpe como Estrés hayas marcado, repartidos entre ellos como quieras."},
{"id":"invigoration","n":"Vigorizar","en":"Invigoration","lv":10,"d":"Splendor","ty":"Spell","rc":3,"t":"Cuando tú o un aliado a distancia Cercana hayáis usado un efecto con límite de usos (como una vez por descanso o una vez por sesión), puedes gastar las Esperanzas que quieras y tirar esa cantidad de d6. Si alguno saca un 6, el efecto se puede volver a usar."},
{"id":"resurrection","n":"Resurrección","en":"Resurrection","lv":10,"d":"Splendor","ty":"Spell","rc":2,"t":"Haz una Tirada de Lanzamiento (20). Si tienes éxito, devuelve con todas sus fuerzas a una criatura que lleve muerta no más de 100 años. Después, tira un d6. Con un 5 o menos, pon esta carta en tu baúl para siempre. Si fallas, no puedes volver a lanzar Resurrección durante una semana."},
{"id":"bare-bones","n":"En los huesos","en":"Bare Bones","lv":1,"d":"Valor","ty":"Ability","rc":0,"t":"Cuando decidas no equiparte armadura, tienes una Puntuación de Armadura base de 3 + tu Fuerza y usas estos umbrales de daño base:\n• Tier 1: 9/19\n• Tier 2: 11/24\n• Tier 3: 13/31\n• Tier 4: 15/38"},
{"id":"forceful-push","n":"Empujón brutal","en":"Forceful Push","lv":1,"d":"Valor","ty":"Ability","rc":0,"t":"Ataca con tu arma principal a un objetivo a distancia Cuerpo a cuerpo. Si tienes éxito, le haces daño y lo empujas hasta distancia Cercana. Si tienes éxito con Esperanza, suma un d6 a tu tirada de daño. Además, puedes gastar una Esperanza para dejarlo Vulnerable de forma temporal."},
{"id":"i-am-your-shield","n":"Soy tu escudo","en":"I Am Your Shield","lv":1,"d":"Valor","ty":"Ability","rc":1,"t":"Cuando un aliado a distancia Muy Cercana vaya a recibir daño, puedes marcar un Estrés para ponerte en medio y ser tú el objetivo del ataque. Cuando recibas el daño de ese ataque, puedes marcar las casillas de Armadura que quieras."},
{"id":"body-basher","n":"Ariete","en":"Body Basher","lv":2,"d":"Valor","ty":"Ability","rc":1,"t":"Usas toda la fuerza de tu cuerpo en la pelea. Cuando aciertes un ataque con un arma de alcance Cuerpo a cuerpo, ganas a tu tirada de daño un bonificador igual a tu Fuerza."},
{"id":"bold-presence","n":"Presencia audaz","en":"Bold Presence","lv":2,"d":"Valor","ty":"Ability","rc":0,"t":"Cuando hagas una Tirada de Presencia, puedes gastar una Esperanza para sumar tu Fuerza a la tirada. Además, una vez por descanso, cuando fueras a sufrir un estado, puedes describir cómo te ayuda tu audacia y evitarlo."},
{"id":"critical-inspiration","n":"Inspiración crítica","en":"Critical Inspiration","lv":3,"d":"Valor","ty":"Ability","rc":1,"t":"Una vez por descanso, cuando consigas un éxito crítico en un ataque, todos los aliados a distancia Muy Cercana pueden recuperar un Estrés o ganar una Esperanza."},
{"id":"lean-on-me","n":"Apóyate en mí","en":"Lean on Me","lv":3,"d":"Valor","ty":"Ability","rc":1,"t":"Una vez por descanso largo, cuando consueles o animes a un aliado que haya fallado una Tirada de Acción, ambos recuperáis 2 de Estrés."},
{"id":"goad-them-on","n":"Provocar","en":"Goad Them on","lv":4,"d":"Valor","ty":"Ability","rc":1,"t":"Describe cómo provocas a un objetivo a distancia Cercana y haz una Tirada de Presencia contra él. Si tienes éxito, el objetivo debe marcar un Estrés y, la próxima vez que el DM le dé el foco, debe atacarte a ti, con desventaja."},
{"id":"support-tank","n":"Muro de apoyo","en":"Support Tank","lv":4,"d":"Valor","ty":"Ability","rc":2,"t":"Cuando un aliado a distancia Cercana falle una tirada, puedes gastar 2 de Esperanza para que repita su dado de Esperanza o el de Miedo."},
{"id":"armorer","n":"Armero","en":"Armorer","lv":5,"d":"Valor","ty":"Ability","rc":1,"t":"Mientras lleves armadura, ganas +1 a tu Puntuación de Armadura. Durante un descanso, cuando elijas reparar tu armadura como movimiento de tiempo libre, tus aliados también recuperan una casilla de Armadura."},
{"id":"rousing-strike","n":"Golpe enardecedor","en":"Rousing Strike","lv":5,"d":"Valor","ty":"Ability","rc":1,"t":"Una vez por descanso, cuando consigas un éxito crítico en un ataque, tú y todos los aliados que puedan verte u oírte podéis recuperar un Punto de Golpe o 1d4 de Estrés."},
{"id":"inevitable","n":"Inevitable","en":"Inevitable","lv":6,"d":"Valor","ty":"Ability","rc":1,"t":"Cuando falles una Tirada de Acción, tu siguiente Tirada de Acción tiene ventaja."},
{"id":"rise-up","n":"En pie","en":"Rise Up","lv":6,"d":"Valor","ty":"Ability","rc":2,"t":"Ganas a tu umbral Grave un bonificador igual a tu Competencia. Cuando marques 1 o más Puntos de Golpe por un ataque, recuperas un Estrés."},
{"id":"shrug-it-off","n":"Ni me inmuto","en":"Shrug It Off","lv":7,"d":"Valor","ty":"Ability","rc":1,"t":"Cuando vayas a recibir daño, puedes marcar un Estrés para reducir la gravedad del daño un umbral. Al hacerlo, tira un d6. Con un 3 o menos, pon esta carta en tu baúl."},
{"id":"valor-touched","n":"Tocado por el Valor","en":"Valor-Touched","lv":7,"d":"Valor","ty":"Ability","rc":1,"t":"Cuando 4 o más cartas de dominio de tu mano sean del dominio Valor, obtienes estos beneficios:\n• +1 a tu Puntuación de Armadura.\n• Cuando marques 1 o más Puntos de Golpe sin marcar una casilla de Armadura, recuperas una casilla de Armadura."},
{"id":"full-surge","n":"A pleno rendimiento","en":"Full Surge","lv":8,"d":"Valor","ty":"Ability","rc":1,"t":"Una vez por descanso largo, marca 3 de Estrés para llevar tu cuerpo al límite. Ganas +2 a todos tus rasgos hasta tu siguiente descanso."},
{"id":"ground-pound","n":"Golpe al suelo","en":"Ground Pound","lv":8,"d":"Valor","ty":"Ability","rc":2,"t":"Gasta 2 de Esperanza para golpear el suelo donde estás y haz una Tirada de Fuerza contra todos los objetivos a distancia Muy Cercana. Los objetivos contra los que tengas éxito salen despedidos hasta distancia Lejana y deben hacer una Tirada de Reacción (17). Los que fallen reciben 4d10+8 de daño. Los que tengan éxito reciben la mitad del daño."},
{"id":"hold-the-line","n":"Mantener la línea","en":"Hold the Line","lv":9,"d":"Valor","ty":"Ability","rc":1,"t":"Describe la postura defensiva que adoptas y gasta una Esperanza. Si un adversario se acerca a distancia Muy Cercana, es atraído a distancia Cuerpo a cuerpo e Inmovilizado. Este estado dura hasta que te muevas o falles una tirada con Miedo, o hasta que el DM gaste 2 Miedos en su turno para quitarlo."},
{"id":"lead-by-example","n":"Predicar con el ejemplo","en":"Lead By Example","lv":9,"d":"Valor","ty":"Ability","rc":3,"t":"Cuando hagas daño a un adversario, puedes marcar un Estrés y describir cómo animas a tus aliados. El siguiente PJ que ataque a ese adversario puede recuperar un Estrés o ganar una Esperanza."},
{"id":"unbreakable","n":"Inquebrantable","en":"Unbreakable","lv":10,"d":"Valor","ty":"Ability","rc":4,"t":"Cuando marques tu último Punto de Golpe, en vez de hacer un Movimiento de Muerte, puedes tirar un d6 y recuperar tantos Puntos de Golpe como el resultado. Después, pon esta carta en tu baúl."},
{"id":"unyielding-armor","n":"Armadura implacable","en":"Unyielding Armor","lv":10,"d":"Valor","ty":"Ability","rc":1,"t":"Cuando vayas a marcar una casilla de Armadura, tira tantos d6 como tu Competencia. Si alguno saca un 6, reduce la gravedad un umbral sin marcar la casilla de Armadura."}];
const CARTA=Object.fromEntries(CARTAS_DOMINIO.map(c=>[c.id,c]));
